import { test, expect } from '@playwright/test';

test.describe('Form Submission Errors Scroll Into View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should scroll error messages into view when form validation fails', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/form-submit', (route) => {
      route.abort('Validation failed');
    });

    // Fill in invalid form fields
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('weakpassword');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is visible
    const errorMessage = page.getByText('Name is required');
    await expect(errorMessage).toBeVisible();

    // Verify error message is at the top of the viewport
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toBeVisible();

    // Verify error message is scrollable
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toBeVisible();

    // Verify form fields are still visible
    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    // Verify error message is visible when scrolling
    await page.evaluate(() => {
      window.scrollBy(0, 1000);
    });
    await expect(errorMessage).toBeVisible();
  });

  test('should not scroll error messages when form is valid', async ({ page }) => {
    // Fill in valid form fields
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane.smith@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is not visible
    const errorMessage = page.getByText('Name is required');
    await expect(errorMessage).not.toBeVisible();

    // Verify form fields are still visible
    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    // Verify error message does not scroll into view
    await page.evaluate(() => {
      window.scrollBy(0, 1000);
    });
    await expect(errorMessage).not.toBeVisible();
  });
});
